"""
Unified per-task cost/latency metrics across all components of the stack.

This is the single owner of per-task totals. The three components feed it:

  - RLM (recall_from_memory)   via rlm_cost.record_rlm_call
  - planner                    via component_metrics.record_component_call
  - execution agent (ReAct)    via component_metrics.record_component_call

Each task is identified by `run_id` (one ChatSession/SmartRetriever per task;
minted by rlm_cost.new_run_id()). This module accumulates every component's
tokens / cost / latency under that run_id and writes EXACTLY ONE row per task to
`task_metrics.csv` (TASK_METRICS_FILE), with side-by-side per-component columns
plus across-component totals.

Because tau2-bench runs tasks sequentially, a task is flushed when the next
task's first metric arrives (a new run_id); the final task is flushed at exit.

Per-call detail rows are intentionally NOT written here — this file is one row
per task for analysis. (rlm_cost.py still logs its per-recall detail rows to
rlm_metrics.csv for debugging.)

Pricing comes from rlm_cost (single source); callers pass already-summed token
counts and pre-computed cost so this module stays pricing-agnostic.

Env overrides:
  TASK_METRICS_FILE   path to the unified CSV (default ./task_metrics.csv)
"""
from __future__ import annotations

import atexit
import csv
import os
import threading
from datetime import datetime

from fastworkflow.utils.rlm_logger import rlm_log

# Reentrant: _flush_task -> _append_row both need the lock.
_LOCK = threading.RLock()

# Components tracked, in column order.
_COMPONENTS = ("rlm", "planner", "agent", "summarizer", "param_extraction")

_CSV_FIELDS = (
    ["run_id", "timestamp"]
    + [f"{c}_{m}" for c in _COMPONENTS
       for m in ("calls", "input_tokens", "output_tokens", "cost_usd", "duration_s")]
    + ["total_calls", "total_input_tokens", "total_output_tokens",
       "total_cost_usd", "total_duration_s", "task_wall_time_s"]
)

# run_id -> per-component running totals for that task
_accumulator: dict[str, dict] = {}

# Current task identity, for deep components (e.g. param extraction) that have no
# run_id in scope. Set once per task by the top of the stack via set_current_run_id.
_current_run_id: str | None = None

# run_id -> wall-clock start time, set when a task's wall clock is started.
_wall_start: dict[str, float] = {}


def set_current_run_id(run_id: str | None) -> None:
    """Record the active task's run_id so deeply-nested components can attribute
    their cost without plumbing run_id through every call. Set per task."""
    global _current_run_id
    with _LOCK:
        _current_run_id = run_id


def get_current_run_id() -> str | None:
    """Return the active task's run_id (set by set_current_run_id), or None."""
    return _current_run_id


def start_task_wall_clock(run_id: str) -> None:
    """Mark the wall-clock start of a task. Idempotent: first call per run_id wins,
    so the timer spans the whole task even if called again."""
    if not run_id:
        return
    import time
    with _LOCK:
        _wall_start.setdefault(run_id, time.time())


def _new_acc() -> dict:
    return {
        comp: {"calls": 0, "input_tokens": 0, "output_tokens": 0,
               "cost_usd": 0.0, "duration_s": 0.0}
        for comp in _COMPONENTS
    }


def record_usage(run_id: str | None, component: str, usage_totals: dict,
                 duration_s: float) -> None:
    """
    Price a raw dspy usage map and accumulate it. Convenience for deep call sites
    that have a `dspy.track_usage()` result but no pricing in scope.

    `usage_totals` is the output of `UsageTracker.get_total_tokens()`:
    {model: {prompt_tokens, completion_tokens, ...}}. If `run_id` is None, the
    current task's run_id (set via set_current_run_id) is used. Never raises.
    """
    try:
        # Local import avoids a circular import at module load (rlm_cost imports
        # task_metrics; task_metrics only needs rlm_cost's pricing lazily here).
        from fastworkflow.rlm_cost import _compute_cost
        rid = run_id or get_current_run_id()
        if not rid:
            return
        total_in = total_out = 0
        total_cost = 0.0
        for model, usage in (usage_totals or {}).items():
            in_tok = int((usage or {}).get("prompt_tokens", 0) or 0)
            out_tok = int((usage or {}).get("completion_tokens", 0) or 0)
            total_in += in_tok
            total_out += out_tok
            total_cost += _compute_cost(model, in_tok, out_tok)
        record(rid, component, calls=1, input_tokens=total_in,
               output_tokens=total_out, cost_usd=total_cost, duration_s=duration_s)
    except Exception as e:  # metrics must never break the agent
        rlm_log(f"[TASK METRICS] record_usage failed: {e}")


def record(run_id: str, component: str, calls: int, input_tokens: int,
           output_tokens: int, cost_usd: float, duration_s: float) -> None:
    """
    Accumulate one component call into the task's running totals.

    `component` must be one of _COMPONENTS. `cost_usd` is already priced by the
    caller (rlm_cost owns the price table). Safe to call from any component;
    metrics failures never propagate.
    """
    try:
        if component not in _COMPONENTS:
            rlm_log(f"[TASK METRICS] ignoring unknown component '{component}'")
            return
        if not run_id:
            return
        with _LOCK:
            # A new run_id means every earlier task is finished -> flush them.
            if run_id not in _accumulator:
                for prior_id in list(_accumulator.keys()):
                    if prior_id != run_id:
                        _flush_task(prior_id)
                _accumulator[run_id] = _new_acc()

            acc = _accumulator[run_id][component]
            acc["calls"] += int(calls)
            acc["input_tokens"] += int(input_tokens)
            acc["output_tokens"] += int(output_tokens)
            acc["cost_usd"] += float(cost_usd)
            acc["duration_s"] += float(duration_s)
    except Exception as e:  # metrics must never break the agent
        rlm_log(f"[TASK METRICS] record failed: {e}")


def flush_run(run_id: str) -> None:
    """Public: flush one task's row immediately (e.g. from tau2's end-of-task
    reset). Safe to call even if the task had no metrics or was already flushed."""
    try:
        with _LOCK:
            _flush_task(run_id)
    except Exception as e:  # metrics must never break the run
        rlm_log(f"[TASK METRICS] flush_run failed: {e}")


def _flush_task(run_id: str) -> None:
    """Write the single per-task row and drop the accumulator entry.
    Caller must hold _LOCK."""
    acc = _accumulator.pop(run_id, None)
    if acc is None:
        # No LLM metrics recorded for this task. Still emit a row (with wall time)
        # if a wall clock was started, so every task appears; otherwise nothing.
        if run_id not in _wall_start:
            return
        acc = _new_acc()

    row = {
        "run_id": run_id,
        "timestamp": datetime.now().isoformat(timespec="seconds"),
    }
    tot_calls = tot_in = tot_out = 0
    tot_cost = tot_dur = 0.0
    for comp in _COMPONENTS:
        c = acc[comp]
        row[f"{comp}_calls"] = c["calls"]
        row[f"{comp}_input_tokens"] = c["input_tokens"]
        row[f"{comp}_output_tokens"] = c["output_tokens"]
        row[f"{comp}_cost_usd"] = round(c["cost_usd"], 8)
        row[f"{comp}_duration_s"] = round(c["duration_s"], 3)
        tot_calls += c["calls"]
        tot_in += c["input_tokens"]
        tot_out += c["output_tokens"]
        tot_cost += c["cost_usd"]
        tot_dur += c["duration_s"]
    row["total_calls"] = tot_calls
    row["total_input_tokens"] = tot_in
    row["total_output_tokens"] = tot_out
    row["total_cost_usd"] = round(tot_cost, 8)
    row["total_duration_s"] = round(tot_dur, 3)

    # Wall-clock task time (set by tau2 via start_task_wall_clock). Captures
    # everything — LLM calls, tool execution, idle/user-sim time — unlike
    # total_duration_s which sums only the component LLM-call durations.
    import time
    start = _wall_start.pop(run_id, None)
    row["task_wall_time_s"] = round(time.time() - start, 3) if start is not None else ""

    _append_row(row)
    rlm_log(
        f"[TASK METRICS] TASK TOTAL (run={run_id}): "
        f"rlm={acc['rlm']['calls']} planner={acc['planner']['calls']} "
        f"agent={acc['agent']['calls']} summarizer={acc['summarizer']['calls']} "
        f"param_extraction={acc['param_extraction']['calls']} calls | "
        f"in={tot_in} out={tot_out} tokens | cost=${tot_cost:.6f} | "
        f"llm={tot_dur:.2f}s wall={row['task_wall_time_s']}s"
    )


@atexit.register
def _flush_all_remaining() -> None:
    """Flush the final task's row at process exit."""
    with _LOCK:
        for run_id in list(_accumulator.keys()):
            _flush_task(run_id)


def _append_row(row: dict) -> None:
    """Append one row to the unified CSV. Caller must hold _LOCK."""
    path = os.environ.get("TASK_METRICS_FILE", "task_metrics.csv")
    try:
        exists = os.path.exists(path) and os.path.getsize(path) > 0
        with open(path, "a", newline="", encoding="utf-8") as f:
            writer = csv.DictWriter(f, fieldnames=_CSV_FIELDS, extrasaction="ignore")
            if not exists:
                writer.writeheader()
            writer.writerow(row)
    except Exception as e:  # metrics must never break the agent
        rlm_log(f"[TASK METRICS] failed to write metrics row: {e}")
